// Some portions generated by Claude
export type FacetValue = {
  id: string;
  label: string;
  count: number;
  visual?: unknown;
};

/**
 * Merge a limited endpoint histogram with values already present locally.
 * Endpoint counts win for returned values; local values remain available when
 * the endpoint response is truncated (for example by LIMIT 100).
 */
export function mergeFacetValues<T extends FacetValue>(
  localValues: readonly T[],
  endpointValues: readonly FacetValue[],
): T[] {
  const localById = new Map(localValues.map((value) => [value.id, value]));
  const endpointIds = new Set(endpointValues.map((value) => value.id));
  const merged = [
    ...endpointValues.map((value) => ({
      ...(localById.get(value.id) ?? ({} as T)),
      ...value,
    }) as T),
    ...localValues.filter((value) => !endpointIds.has(value.id)),
  ];
  return merged.sort(
    (left, right) =>
      right.count - left.count || left.label.localeCompare(right.label),
  );
}
